require 'open3'

module GitPullRequests
  # A pull request: an issue of the "Pull request" tracker whose custom fields
  # name a source branch and a target branch in a git repository Redmine
  # reads. Only reads the repository, with git itself.
  class PullRequest
    # The Redmine objects the plugin uses, by name: renaming one in Redmine
    # needs the same change here
    TRACKER = 'Pull request'
    SOURCE_FIELD = 'Source branch'
    TARGET_FIELD = 'Target branch'
    MERGED_STATUS = 'Merged'

    # Branch names we accept: no option injection ("-..."), no "..", no
    # characters with a meaning in revision syntax
    BRANCH_NAME = %r{\A(?!-)(?!.*\.\.)[A-Za-z0-9._/-]+\z}
    MAX_COMMITS = 250

    attr_reader :issue, :repository, :source, :target

    def self.pull_request?(issue)
      issue.tracker&.name == TRACKER
    end

    # The git repository for a project: its own, or the nearest ancestor's
    # (subprojects usually share their parent's repository)
    def self.repository_for(project)
      project.self_and_ancestors.reverse_each do |p|
        repos = p.repositories.select {|r| r.is_a?(Repository::Git)}
        repo = repos.detect(&:is_default) || repos.first
        return repo if repo
      end
      nil
    end

    # The open pull requests that use this repository
    def self.open_for(repository)
      Issue.open.joins(:tracker).where(trackers: {name: TRACKER})
           .where(project_id: repository.project.self_and_descendants.select(:id))
           .select {|issue| repository_for(issue.project) == repository}
           .map {|issue| new(issue)}
    end

    def initialize(issue)
      @issue = issue
      @repository = self.class.repository_for(issue.project)
      @source = field_value(SOURCE_FIELD)
      @target = field_value(TARGET_FIELD)
    end

    # Why the changes can't be shown, or nil
    def problem
      return 'This project has no git repository.' unless repository
      # Merged: everything comes from the merge commit, the branches may be gone
      return nil if recorded_merge && source_tip

      return 'No source branch given.' if source.blank?
      return 'No target branch given.' if target.blank?
      invalid = {'source branch' => source, 'target branch' => target}.reject {|_, name| BRANCH_NAME.match?(name)}
      return invalid.map {|field, name| "Invalid #{field} name: #{name}."}.join(' ') if invalid.any?
      return 'Source branch and target branch are the same.' if source == target
      missing = []
      missing << "Source branch #{source} doesn't exist." unless source_tip
      missing << "Target branch #{target} doesn't exist." unless target_tip
      return missing.join(' ') if missing.any?

      nil
    end

    # The commit the source branch is at, or, once merged, was at when merged
    def source_tip
      return @source_tip if defined?(@source_tip)

      @source_tip = recorded_merge ? rev_parse("#{recorded_merge}^2") : rev_parse("refs/heads/#{source}")
    end

    def target_tip
      return @target_tip if defined?(@target_tip)

      @target_tip = rev_parse("refs/heads/#{target}")
    end

    # What the branch is compared with: the target as it is, or, once the
    # branch has been merged, the target just before the merge (so a merged
    # pull request still shows what it brought in)
    def base
      @base ||= merge_commit ? "#{merge_commit}^1" : target_tip
    end

    # Commits on the branch that aren't on the base, newest first:
    # [{id:, author:, date:, subject:}]
    def commits
      @commits ||= git('log', "--max-count=#{MAX_COMMITS}", '--format=%H%x00%an%x00%as%x00%s',
                       "#{base}..#{source_tip}").lines.map do |line|
        id, author, date, subject = line.chomp.split("\0", 4)
        {id: id, author: author, date: date, subject: subject}
      end
    end

    # Where the branch forked from the base: the diff from here to source_tip
    # is what merging brings in (git diff base...source_tip)
    def merge_base
      @merge_base ||= git('merge-base', base, source_tip).strip
    end

    def branch_exists?(name)
      rev_parse("refs/heads/#{name}").present?
    end

    # The merge commit that brought the branch into the target, or nil: the
    # one linked to the issue when it was set to Merged, else found in git.
    # Only a merge counts: a branch without commits of its own (or merged by
    # fast-forward) is on the target's first-parent line already and isn't
    # reported as merged.
    def merge_commit
      return @merge_commit if defined?(@merge_commit)

      @merge_commit = recorded_merge || find_merge_commit
    end

    # The merge commit linked to the issue as an associated revision (by
    # RepositoryGitPatch, when it set the status to Merged), or nil: the
    # newest of the issue's revisions in this repository with two parents.
    # Only while the issue is closed: a reopened pull request is open again
    # for new commits, and is compared with its target as it is.
    def recorded_merge
      return @recorded_merge if defined?(@recorded_merge)
      return @recorded_merge = nil unless issue.closed?

      @recorded_merge = issue.changesets.select {|c| c.repository_id == repository&.id}.reverse
                             .map(&:revision).detect {|sha| rev_parse("#{sha}^2")}
    end

    private

    def find_merge_commit
      return nil if problem
      return nil unless git_ok?('merge-base', '--is-ancestor', source_tip, target_tip)
      return nil if git('rev-list', '--first-parent', target_tip).lines.map(&:chomp).include?(source_tip)

      git('rev-list', '--first-parent', '--ancestry-path', '--reverse', "#{source_tip}..#{target_tip}")
        .lines.first&.chomp
    end

    def field_value(name)
      issue.custom_field_values.detect {|v| v.custom_field.name == name}&.value.to_s.strip
    end

    # The commit a revision names, or nil
    def rev_parse(rev)
      out = git('rev-parse', '--verify', '--quiet', "#{rev}^{commit}")
      out.strip.presence
    rescue CommandFailed
      nil
    end

    class CommandFailed < StandardError; end

    def git_command(*args)
      [Redmine::Scm::Adapters::GitAdapter.client_command, '--git-dir', repository.url, *args]
    end

    def git(*args)
      out, err, status = Open3.capture3(*git_command(*args))
      raise CommandFailed, "git #{args.first}: #{err.strip}" unless status.success?

      out.force_encoding('UTF-8').scrub
    end

    def git_ok?(*args)
      _out, _err, status = Open3.capture3(*git_command(*args))
      status.success?
    end
  end
end
